"""
    Calculates the mean of a list of numbers
    :param args: List of numbers
    :return:  The mean of a list of numbers
    """
def mean(*args: Any) -> object {
    index = 0;
    sum_index = 0;
    for i in args {
        index += 1;
        sum_index += float(i);
    }
    return (sum_index / index) if (index != 0) else "Division by zero";
}

