"""Sum the first N cubes of natural numbers.

    >>> sum_cubes(5)
    225
    """
def sum_cubes(n: Any) -> object {
    (total, k) = (0, 1);
    while (k <= n) {
        (total, k) = ((total + pow(k, 3)), (k + 1));
    }
    return total;
}

