"""
    Calculates the fraction of common elements between two lists
    not taking into account chain IDs. Much Slower.
    """
def calculate_fcc_nc(listA: Any, listB: Any) -> object {
    (largest, smallest) = sorted([listA, listB], key=len);
    ncommon = len(
        [
            ele
            for ele in largest
            if (ele in smallest)
        ]
    );
    return (ncommon, ncommon);
}

"""
    Adds markup around given text.
    Supports some colors by name instead of hexadecimal.

    :param text_str:
    :param color_str: (str) Hexadecimal color.
    :return: (str)
    """
def paint_text(text_str: Any, color_str: Any) -> object {
    return '[color={color_str}]{text_str}[/color]'.format(
        text_str=text_str, color_str=color_str
    );
}

